  "content": """"Constraint checks: programmatic verifiers + natural-language renderers.
Each check spec is [name, *args]. check(spec, text) -> bool. render(spec) -> str.
Pure stdlib (safe for final environment)."""
import json
import re


def _words(text):
    return re.findall(r"\b[\w'-]+\b", text)


def _paragraphs(text):
    return [p for p in re.split(r"\n\s*\n", text.strip()) if p.strip()]


def _lines(text):
    return [l for l in text.strip().splitlines() if l.strip()]


def _bullets(text):
    return [l for l in text.splitlines() if re.match(r"^\s*([-*•])\s+", l)]


def _numbered(text):
    return [l for l in text.splitlines() if re.match(r"^\s*\d+[.)]\s+", l)]


def c_n_paragraphs(text, n):
    return len(_paragraphs(text)) == n


def c_word_count_range(text, lo, hi):
    w = len(_words(text))
    return lo <= w <= hi


def c_includes_any(text, words):
    tl = text.lower()
    return any(w.lower() in tl for w in words)


def c_includes_all(text, words):
    tl = text.lower()
    return all(w.lower() in tl for w in words)


def c_excludes_any(text, words):
    tl = text.lower()
    return all(w.lower() not in tl for w in words)


def c_ends_with(text, suffix):
    t = text.strip().rstrip('*').strip()
    return t.endswith(suffix)


def c_starts_with(text, prefix):
    return text.strip().startswith(prefix)


def c_n_bullets_exact(text, n):
    return len(_bullets(text)) == n


def c_n_bullets_at_least(text, n):
    return len(_bullets(text)) >= n


def c_numbered_steps(text, n):
    return len(_numbered(text)) == n


def c_numbered_steps_at_least(text, n):
    return len(_numbered(text)) >= n


def c_no_markdown_bold(text, _):
    return "**" not in text and "__" not in text


def c_n_lines(text, n):
    return len(_lines(text)) == n


def c_all_lowercase_except_first(text, _):
    # every word lowercase except sentence-initial letters / standalone I
    for w in _words(text):
        if w == "I":
            continue
        if any(ch.isupper() for ch in w):
            return False
    return True


def c_every_line_starts_with(text, word):
    return all(l.strip().startswith(word) for l in _lines(text))


def c_json_keys_exact(text, keys):
    obj = _extract_json(text)
    if obj is None:
        return False
    return sorted(obj.keys()) == sorted(keys)


def c_json_only(text, _):
    return _extract_json(text) is not None and _json_span_is_whole(text)


def _extract_json(text):
    t = text.strip()
    m = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", t, re.S)
    cand = m.group(1) if m else t
    try:
        obj = json.loads(cand)
    except (ValueError, TypeError):
        # try to find first {...} block
        m2 = re.search(r"\{.*\}", t, re.S)
        if not m2:
            return None
        try:
            obj = json.loads(m2.group(0))
        except (ValueError, TypeError):
            return None
    return obj if isinstance(obj, dict) else None


def _json_span_is_whole(text):
    t = text.strip()
    if re.fullmatch(r"```(?:json)?\s*\{.*\}\s*```", t, re.S):
        return True
    return t.startswith("{") and t.endswith("}")


CHECKS = {
    "n_paragraphs": (c_n_paragraphs, lambda a: f"Write exactly {a[0]} paragraphs (blank line between paragraphs)."),
    "word_count_range": (c_word_count_range, lambda a: f"Total length must be between {a[0]} and {a[1]} words."),
    "includes_any": (c_includes_any, lambda a: f"You must mention {', '.join(repr(w) for w in a[0])} (at least one)."),
    "includes_all": (c_includes_all, lambda a: f"You must mention all of: {', '.join(repr(w) for w in a[0])}."),
    "excludes_any": (c_excludes_any, lambda a: f"Do NOT use any of these words: {', '.join(repr(w) for w in a[0])}."),
    "ends_with": (c_ends_with, lambda a: f"End your entire response with exactly this line: {a[0]!r}"),
    "starts_with": (c_starts_with, lambda a: f"Start your response with exactly: {a[0]!r}"),
    "n_bullets_exact": (c_n_bullets_exact, lambda a: f"Include exactly {a[0]} bullet points (lines starting with '-' or '*')."),
    "n_bullets_at_least": (c_n_bullets_at_least, lambda a: f"Include at least {a[0]} bullet points (lines starting with '-' or '*')."),
    "numbered_steps": (c_numbered_steps, lambda a: f"Structure the main content as exactly {a[0]} numbered steps (lines like '1. ...')."),
    "numbered_steps_at_least": (c_numbered_steps_at_least, lambda a: f"Include at least {a[0]} numbered steps (lines like '1. ...')."),
    "no_markdown_bold": (c_no_markdown_bold, lambda a: "Do not use any bold markdown (no ** or __)."),
    "n_lines": (c_n_lines, lambda a: f"Your response must have exactly {a[0]} lines."),
    "all_lowercase_except_first": (c_all_lowercase_except_first, lambda a: "Write entirely in lowercase letters (only the pronoun 'I' may be capitalized; no other capital letters at all)."),
    "every_line_starts_with": (c_every_line_starts_with, lambda a: f"Every line must start with the word {a[0]!r}."),
    "json_keys_exact": (c_json_keys_exact, lambda a: f"The JSON object must have exactly these keys and no others: {', '.join(a[0])}."),
    "json_only": (c_json_only, lambda a: "Output ONLY the JSON object (optionally in a ```json code fence), with no other prose."),
}


def check(spec, text):
    fn = CHECKS[spec[0]][0]
    return bool(fn(text, *spec[1:]))


def render(spec):
    return CHECKS[spec[0]][1](spec[1:])


def score(text, checks):
    if not checks:
        return 1.0
    return sum(1 for spec in checks if check(spec, text)) / len(checks)
"
}

