  "content": """"Assemble full question bank -> submission/assets/questions.json + evaluation.json."""
import json
from coding_impl import IMPL, DEBUG, PREDICT
import coding_debug  # noqa: F401
from cowork_constraint import CONSTRAINT_TASKS
from cowork_rubric import RUBRIC_TASKS
from constraint_checks import render

QUESTIONS = []

# ---- reasoning ----
for q in json.load(open('/workspace/work/reasoning_items.json')):
    g = q['grader']
    mt = 8192 if g['kind'] != 'judge_math' else 12288
    QUESTIONS.append({
        "id": q['id'], "question_id": q['id'], "domain": q['domain'],
        "prompt": q['prompt'], "max_tokens": mt, "grader": g,
        "weight": 1.0, "source": q.get('source'),
    })

# ---- coding ----
IMPL_INSTR = (
    "\n\nRequirements:\n"
    "- Respond with exactly one ```python``` code block containing the complete solution.\n"
    "- Do not include any explanation, example usage, or test code outside the code block.\n"
    "- Name the required function/class exactly as specified."
)
for t in IMPL:
    QUESTIONS.append({
        "id": t['id'], "question_id": t['id'], "domain": "coding",
        "prompt": "Implement the following in Python.\n\n" + t['spec'] + IMPL_INSTR,
        "max_tokens": 8192,
        "grader": {"kind": "code", "tests": t['tests'], "entry": t['entry']},
        "weight": 1.0, "source": "synthetic",
    })

for t in DEBUG:
    prompt = (
        "The following Python code has a bug.\n\n```python\n" + t['buggy'] + "```\n\n"
        "Observed problem: " + t['bug_desc'] + "\n\n"
        "Rewrite the COMPLETE corrected code in a single ```python``` code block. "
        "Keep the same function/class names and signatures. Do not include explanations or tests."
    )
    QUESTIONS.append({
        "id": t['id'], "question_id": t['id'], "domain": "coding",
        "prompt": prompt, "max_tokens": 8192,
        "grader": {"kind": "code", "tests": t['tests'], "entry": t['entry']},
        "weight": 1.0, "source": "synthetic",
    })

for t in PREDICT:
    prompt = (
        "Read this Python program carefully.\n\n```python\n" + t['code'] + "```\n\n"
        + t['question'] + " Respond with ONLY the exact output, no explanation and no code fences."
    )
    QUESTIONS.append({
        "id": t['id'], "question_id": t['id'], "domain": "coding",
        "prompt": prompt, "max_tokens": 4096,
        "grader": {"kind": "exact_text", "answer": t['answer']},
        "weight": 1.0, "source": "synthetic",
    })

# ---- co-work: constraint ----
for t in CONSTRAINT_TASKS:
    req = "\n".join(f"- {render(c)}" for c in t['checks'])
    prompt = (t['task'] + "\n\nFollow ALL of these requirements exactly:\n" + req +
              "\n\nRespond with only the requested content; do not explain.")
    QUESTIONS.append({
        "id": t['id'], "question_id": t['id'], "domain": "co-work",
        "prompt": prompt, "max_tokens": 4096,
        "grader": {"kind": "constraint", "checks": t['checks']},
        "weight": 1.0, "source": "synthetic",
    })

# ---- co-work: rubric ----
for t in RUBRIC_TASKS:
    QUESTIONS.append({
        "id": t['id'], "question_id": t['id'], "domain": "co-work",
        "prompt": t['task'], "max_tokens": 6144,
        "grader": {"kind": "rubric", "occupation": t['occupation'], "rubric": t['rubric']},
        "weight": 1.0, "source": "synthetic",
    })

# sanity
assert len(QUESTIONS) == len({q['id'] for q in QUESTIONS}), "duplicate ids"
domains = {}
for q in QUESTIONS:
    domains.setdefault(q['domain'], []).append(q['id'])
print({d: len(v) for d, v in domains.items()}, "TOTAL", len(QUESTIONS))

json.dump(QUESTIONS, open('/workspace/submission/assets/questions.json', 'w'), indent=1)

# ---- evaluation.json ----
ev = {
    "protocol_version": 1,
    "items": [{"id": q['id'], "question_id": q['id'], "weight": 1.0} for q in QUESTIONS],
    "questions": [{"id": q['id'], "prompt": q['prompt']} for q in QUESTIONS],
    "selection": "fixed",
    "aggregation": {"kind": "weighted_mean"},
    "domain_aggregations": {
        d: {"kind": "weighted_mean", "weights": {i: 1.0 for i in ids}}
        for d, ids in domains.items()
    },
}
json.dump(ev, open('/workspace/submission/evaluation.json', 'w'), indent=1)
print("evaluation.json written")
